import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { NgFor, NgIf } from '@angular/common';
import { ApiService } from '../../services/api.service';
import { AdminAccessService } from '../../services/admin-access.service';
import { Tournament, Registration } from '../../models/models';

@Component({
  selector: 'app-tournaments',
  standalone: true,
  imports: [FormsModule, NgFor, NgIf],
  template: `
<section class="tournament-page">
  <h2>{{ editMode ? 'Edit Tournament' : 'Add Tournament' }}</h2>

  <div class="card" *ngIf="!editMode && isSuperAdmin()" style="padding:14px;margin-bottom:14px">
    <h3>Import Registered Players (Optional)</h3>
    <p class="muted">Upload the Excel/CSV file downloaded from an existing tournament. The players will be imported into this NEW tournament after creation; the original tournament will not be changed.</p>
    <input type="file" accept=".xlsx,.xls,.csv,.txt" (change)="selectNewTournamentRoster($event)" [disabled]="rosterImportBusy">
    <small *ngIf="newTournamentRoster">Selected: {{newTournamentRoster.name}}</small>
    <p *ngIf="rosterImportMessage">{{rosterImportMessage}}</p>
  </div>
  <div class="card tournament-form-card">
    <div class="tournament-form-grid">
      <div class="field-group name-field">
        <label>Tournament Name <span class="required">*</span></label>
        <input [(ngModel)]="model.name" placeholder="Tournament Name">
      </div>

      <div class="format-section">
        <label>Select Tournament Format(s) <span class="required">*</span></label>
        <small class="muted">Select one or more formats to open registrations for this tournament.</small>

        <label class="format-card" *ngFor="let f of allFormats">
          <input type="checkbox" [checked]="isFormatSelected(f)" (change)="toggleFormat(f, $event)">
          <span class="format-text">
            <b>{{f}}</b>
            <small>{{formatDescription(f)}}</small>
          </span>
        </label>
      </div>

      <div class="field-group date-field" *ngIf="!multiFormatSelected()">
        <label>Tournament Date <span class="required">*</span></label>
        <input [(ngModel)]="model.tournamentDate" type="date">
      </div>

      <div class="field-group date-field" *ngIf="multiFormatSelected()">
        <label>Tournament From Date <span class="required">*</span></label>
        <input [(ngModel)]="model.tournamentDate" type="date">
      </div>

      <div class="field-group date-field" *ngIf="multiFormatSelected()">
        <label>Tournament To Date <span class="required">*</span></label>
        <input [(ngModel)]="model.tournamentEndDate" type="date">
      </div>

      <div class="field-group date-field">
        <label>Tournament Start Time</label>
        <input [(ngModel)]="model.tournamentStartTime" type="time">
      </div>

      <div class="field-group date-field">
        <label>Tournament End Time</label>
        <input [(ngModel)]="model.tournamentEndTime" type="time">
      </div>

      <div class="field-group fee-field">
        <label>Registration Fee ($)</label>
        <input [(ngModel)]="model.registrationFee" type="number" min="0" placeholder="0">
      </div>


      <div class="schedule-preview">
        <b>Schedule Preview</b>
        <span>{{modelSchedule()}}</span>
        <span *ngIf="modelTime()">Time: {{modelTime()}}</span>
      </div>

      <div class="field-group venue-field">
        <label>Venue Address</label>
        <input [(ngModel)]="model.address" placeholder="Physical tournament address">
      </div>

      <div class="field-group venue-field">
        <label>Tournament Day Live - YouTube Video / Live Link</label>
        <input [(ngModel)]="model.liveUrl" placeholder="Paste YouTube Live or YouTube video link">
        <small class="muted">Admin can paste a YouTube Live or YouTube video link here. It becomes publicly visible only after SRR Round 1 is generated.</small>
      </div>

      <div class="field-group count-field">
        <label>{{ participantCountLabel() }}</label>
        <input [(ngModel)]="model.totalNumberOfPlayers" type="number" min="2">
      </div>

      <div class="field-group srr-field">
        <label># SRR Rounds <span class="required">*</span></label>
        <input [(ngModel)]="model.srrRounds" type="number" min="1" max="7">
        <small class="muted">Admin can edit this later on game day if time constraints require fewer/more SRR rounds.</small>
      </div>

      <div class="field-group ko-field">
        <label># Knockout Rounds</label>
        <input [(ngModel)]="model.knockoutRounds" type="number" min="0">
      </div>

      <div *ngIf="isFormatSelected('Team Event')" class="team-box team-event-field">
        <label>Team Event Players Per Team <span class="required">*</span></label>
        <select [(ngModel)]="model.playersPerTeam" (ngModelChange)="resizeTeamPlayers()">
          <option [ngValue]="3">3 Players</option>
          <option [ngValue]="4">4 Players</option>
          <option [ngValue]="5">5 Players</option>
          <option [ngValue]="6">6 Players</option>
          <option [ngValue]="7">7 Players</option>
          <option [ngValue]="8">8 Players</option>
        </select>

        <label>Team Name</label>
        <input [(ngModel)]="model.teamName" placeholder="Optional Team Name">

        <label>Player Names</label>
        <input *ngFor="let p of model.teamPlayerNames; let i=index" [(ngModel)]="model.teamPlayerNames![i]" placeholder="Player {{i+1}} name optional">
      </div>


      <div class="discount-section">
        <h3>Discount Setup</h3>
        <p class="muted">Select discounts the organizer wants to offer. These will appear on registration page and deduct from final fee.</p>

        <div class="discount-card" *ngFor="let d of model.discountOptions">
          <label class="discount-enable">
            <input type="checkbox" [(ngModel)]="d.enabled">
            <b>{{d.label}}</b>
          </label>
          <input type="number" min="0" [(ngModel)]="d.amount" placeholder="Discount Amount">
          <textarea *ngIf="needsNameList(d.type)" [(ngModel)]="d.eligibleNamesText" placeholder="Enter eligible names separated by comma or new line"></textarea>
          <small class="muted" *ngIf="needsNameList(d.type)">Names entered here show as dropdown during registration.</small>
          <small class="muted" *ngIf="d.type === 'WOMEN'">Registration page will show Gender selection for this discount.</small>
        </div>
      </div>

      <div class="field-group pin-field" *ngIf="!editMode">
        <label>Organization / Tournament Admin PIN <span class="required">*</span></label>
        <div class="pin-row">
          <input class="pin-input-short" [type]="showAdminPin ? 'text' : 'password'" [(ngModel)]="model.adminPin" placeholder="4-digit PIN" maxlength="4" inputmode="numeric" autocomplete="off">
          <button type="button" class="secondary pin-toggle-btn" (click)="showAdminPin = !showAdminPin">{{ showAdminPin ? 'Hide' : 'Show' }}</button>
        </div>
        <small class="muted">Each organization can create its own 4-digit tournament admin PIN to protect tournament management from unauthorized users.</small>
      </div>
      <div class="field-group pin-field" *ngIf="editMode">
        <label>Admin Authorization</label>
        <div class="muted">Editing with your current authenticated Admin session. Tournament ownership PIN is not changed.</div>
      </div>

      <div class="field-group description-field-wrap">
        <label class="full-line-label">Description</label>
        <textarea class="description-field" [(ngModel)]="model.description" placeholder="Description"></textarea>
      </div>

      <div class="action-row form-actions">
        <button (click)="save()" [disabled]="rosterImportBusy">{{ editMode ? 'Update Tournament' : 'Create Tournament' }}</button>
        <button type="button" class="secondary" *ngIf="editMode" (click)="cancelEdit()">Cancel Edit</button>
      </div>
    </div>
  </div>
</section>

<h3>Manage Tournament</h3>
<p class="muted">Super Admin can view all OPEN, COMPLETED, hidden, and soft-removed tournaments. Tournament admins see tournaments owned by their Admin PIN.</p>
<div class="table-scroll manage-tournament-scroll">
<table>
  <tr>
    <th>Name</th><th>Formats</th><th>Date</th><th>Fee</th><th>Address</th><th>SRR</th><th>KO</th><th>Status</th><th *ngIf="isSuperAdmin()">Record</th><th *ngIf="isSuperAdmin()">Hidden</th><th>Action</th>
  </tr>
  <tr *ngFor="let t of tournaments">
    <td>{{t.name}}</td>
    <td>{{(t.formats || []).join(', ')}}</td>
    <td>{{tournamentSchedule(t)}}<br><small *ngIf="tournamentTime(t)">Time: {{tournamentTime(t)}}</small></td>
    <td>{{ currencySymbol }}{{t.registrationFee || 0}}</td>
    <td>{{t.address}}</td>
    <td>{{t.srrRounds}}</td>
    <td>{{t.knockoutRounds}}</td>
    <td>{{t.status}}</td>
    <td *ngIf="isSuperAdmin()">{{isRemoved(t) ? 'REMOVED' : 'ACTIVE'}}</td>
    <td *ngIf="isSuperAdmin()">{{t.hiddenFromDashboard ? 'Yes' : 'No'}}</td>
    <td>
      <button type="button" class="secondary small" *ngIf="!isRemoved(t)" (click)="viewRegisteredPlayers(t)">View Players</button>
      <button type="button" class="secondary small" *ngIf="!isRemoved(t)" (click)="editTournament(t)">Edit</button>
      <button type="button" class="black-btn small" *ngIf="isSuperAdmin() && !isRemoved(t)" (click)="toggleDashboardVisibility(t)">{{t.hiddenFromDashboard ? 'Show Publicly' : 'Hide Publicly'}}</button>
      <button type="button" class="yellow-btn small" *ngIf="!isRemoved(t) && (t.status || 'OPEN') !== 'COMPLETED'" (click)="completeTournament(t)">Complete Tournament</button>
      <button type="button" class="secondary small" *ngIf="!isRemoved(t) && t.status === 'COMPLETED'" (click)="reopenTournament(t)">Reopen</button>
      <button type="button" class="danger small" *ngIf="!isRemoved(t)" (click)="askDelete(t)">Remove</button>
      <button type="button" class="secondary small" *ngIf="isSuperAdmin() && isRemoved(t)" (click)="restoreTournament(t)">Restore</button>
    </td>
  </tr>
</table>
</div>


<div class="card" *ngIf="selectedPlayersTournament">
  <h3>Registered Players - {{selectedPlayersTournament.name}}</h3>
  <p class="muted" *ngIf="selectedTournamentPlayers.length === 0">No players registered yet.</p>
  <div class="table-scroll" *ngIf="selectedTournamentPlayers.length">
    <table>
      <tr><th>#</th><th>Player</th><th>Format</th><th>Partner</th><th>Email</th><th>Phone</th><th>Payment</th></tr>
      <tr *ngFor="let p of selectedTournamentPlayers; let i=index">
        <td>{{i+1}}</td>
        <td>{{p.playerName}}</td>
        <td>{{p.format}}</td>
        <td>{{p.partnerName || '-'}}</td>
        <td>{{p.email}}</td>
        <td>{{p.phone}}</td>
        <td>{{p.paymentStatus}}</td>
      </tr>
    </table>
  </div>
</div>

<div class="card form delete-confirm" *ngIf="pendingDelete">
  <h3>Remove Tournament</h3>
  <p>Enter tournament Admin PIN or Super Admin PIN to remove <b>{{pendingDelete.name}}</b> from active views. Registrations, matches, scores and history are preserved.</p>
  <label>Admin PIN <span class="required">*</span></label>
  <input type="password" [(ngModel)]="deletePin" placeholder="Enter admin PIN" autocomplete="off">
  <div class="action-row">
    <button type="button" class="danger" (click)="confirmDelete()">Confirm Remove</button>
    <button type="button" class="secondary" (click)="cancelDelete()">Cancel</button>
  </div>
</div>`
})
export class TournamentsComponent implements OnInit {
  tournaments: Tournament[]=[];
  selectedPlayersTournament?: Tournament;
  selectedTournamentPlayers: Registration[] = [];
  allFormats = ['Singles','Doubles','Mixed Doubles','Team Event'];
  currencySymbol = '$';
  showAdminPin = false;
  deletePin = '';
  pendingDelete?: Tournament;
  editMode = false;
  model: Tournament=this.emptyModel();

  constructor(private api:ApiService, private admin: AdminAccessService, private route: ActivatedRoute){}
  isSuperAdmin(){ return this.admin.isSuperAdmin(); }
  toggleDashboardVisibility(t:Tournament){
    if(!t.id) return;
    this.api.setTournamentDashboardHidden(t.id, !t.hiddenFromDashboard, this.admin.currentPin()).subscribe({
      next: updated => { t.hiddenFromDashboard = updated.hiddenFromDashboard; },
      error: err => alert(err?.error?.message || err?.error || 'Unable to update visibility.')
    });
  }

  ngOnInit(){ this.load(); }
  load(){
    this.api.manageTournaments(this.admin.currentPin()).subscribe({
      next: x => {
        this.tournaments = x || [];
        this.openRequestedTournamentForEdit();
      },
      error: err => {
        this.tournaments = [];
        alert(this.displayError(err));
      }
    });
  }
  private openRequestedTournamentForEdit(): void {
    const requestedId = this.route.snapshot.queryParamMap.get('editTournamentId');
    if (!requestedId || this.editMode) return;
    const tournament = this.tournaments.find(t => t.id === requestedId);
    if (tournament) this.editTournament(tournament);
  }
  isRemoved(t:Tournament): boolean { return (t.recordStatus || '').toUpperCase() === 'D'; }
  restoreTournament(t:Tournament){
    if(!t.id || !this.isSuperAdmin()) return;
    this.api.restoreTournament(t.id, this.admin.currentPin()).subscribe({
      next: () => this.load(),
      error: err => alert(this.displayError(err))
    });
  }

  emptyModel(): Tournament { return {name:'', tournamentType:'', registrationFee: 0, srrRounds:5, knockoutRounds:1, formats:['Singles'], status:'OPEN', adminPin:'', playersPerTeam:3, teamPlayerNames:[], discountOptions: this.defaultDiscountOptions() as any, tournamentStartTime:'09:00', tournamentEndTime:'19:00'}; }
  defaultDiscountOptions(){
    return [
      {type:'EC_TEAM', label:'EC Team Discount', amount:0, enabled:false, eligibleNames:[]},
      {type:'PRESIDENT_PANEL', label:'President Panel Discount', amount:0, enabled:false, eligibleNames:[]},
      {type:'LIFETIME_MEMBER', label:'Life Time Members Discount', amount:0, enabled:false, eligibleNames:[]},
      {type:'WOMEN', label:'Women Player Discount', amount:0, enabled:false, eligibleNames:[]},
      {type:'SENIOR', label:'Senior Citizen Discount', amount:0, enabled:false, eligibleNames:[]},
      {type:'UNDER_21', label:'Under 21 Discount', amount:0, enabled:false, eligibleNames:[]},
      {type:'UNDER_18', label:'Under 18 Discount', amount:0, enabled:false, eligibleNames:[]}
    ];
  }
  multiFormatSelected(){ return (this.model.formats || []).length > 1; }
  needsNameList(type:string){ return ['EC_TEAM','PRESIDENT_PANEL','LIFETIME_MEMBER'].includes(type); }
  normalizeDiscountOptions(){
    this.model.discountOptions = (this.model.discountOptions || this.defaultDiscountOptions() as any).map((d:any)=>({
      ...d,
      amount: Number(d.amount || 0),
      eligibleNames: this.parseNames(d.eligibleNamesText || (d.eligibleNames || []).join(','))
    }));
  }
  parseNames(value:string): string[] {
    return String(value || '').split(/[\n,]+/).map(v=>v.trim()).filter(v=>v);
  }
  onTournamentTypeChange(){ this.resizeTeamPlayers(); }
  isFormatSelected(format:string){ return (this.model.formats || []).includes(format); }
  toggleFormat(format:string, event:any){
    const checked = event?.target?.checked;
    const existing = this.model.formats || [];
    this.model.formats = checked ? Array.from(new Set([...existing, format])) : existing.filter(f => f !== format);
    if(this.model.formats.length === 0) this.model.formats = ['Singles'];
    this.model.tournamentType = this.model.formats[0] || '';
    this.resizeTeamPlayers();
  }

  mergeDiscountOptions(existing:any[] = []) {
    const defs:any[] = this.defaultDiscountOptions();
    return defs.map(d => ({
      ...d,
      ...((existing || []).find((e:any) => e.type === d.type) || {})
    }));
  }

  formatDescription(format:string){
    if(format === 'Singles') return 'Individual matches (1 vs 1)';
    if(format === 'Doubles') return 'Two players per team (2 vs 2)';
    if(format === 'Mixed Doubles') return 'One male and one female per team (2 vs 2)';
    if(format === 'Team Event') return 'Organization team championship format';
    return '';
  }
  resizeTeamPlayers(){
    const count = this.isFormatSelected('Team Event') ? Number(this.model.playersPerTeam || 3) : 0;
    this.model.teamPlayerNames = Array.from({length: count}, (_,i)=> this.model.teamPlayerNames?.[i] || '');
  }
  participantCountLabel(){ return this.model.formats?.some(f => f === 'Doubles' || f === 'Mixed Doubles' || f === 'Team Event') ? 'Total Number of Teams' : 'Total Number of Players'; }
  newTournamentRoster?: File;
  rosterImportBusy = false;
  rosterImportMessage = '';
  selectNewTournamentRoster(event: Event) {
    const input = event.target as HTMLInputElement;
    const file = input.files?.[0];
    this.newTournamentRoster = file && /\.(xlsx|xls|csv|txt)$/i.test(file.name) ? file : undefined;
    this.rosterImportMessage = file && !this.newTournamentRoster ? 'Please select an Excel or CSV roster file.' : '';
  }
  save(){
    if (this.rosterImportBusy) return;
    if(!this.model.formats || this.model.formats.length === 0) this.model.formats=['Singles'];
    this.model.tournamentType = this.model.formats[0] || '';
    this.model.registrationFee = Number(this.model.registrationFee || 0);
    this.normalizeDiscountOptions();
    this.model.srrRounds = Number(this.model.srrRounds || 5);
    this.model.knockoutRounds = Number(this.model.knockoutRounds || 0);
    this.model.totalNumberOfPlayers = this.model.totalNumberOfPlayers ? Number(this.model.totalNumberOfPlayers) : undefined;
    if (!this.editMode) {
      this.model.adminPin = (this.model.adminPin || '').replace(/[^0-9]/g, '').slice(0, 4);
      if (!this.model.adminPin || this.model.adminPin.length !== 4) {
        alert('Please enter a 4-digit Tournament Admin PIN.');
        return;
      }
    }
    if (!this.multiFormatSelected()) {
      this.model.tournamentEndDate = undefined;
    } else if (!this.model.tournamentEndDate) {
      this.model.tournamentEndDate = this.model.tournamentDate;
    }
    this.model.tournamentStartTime = this.model.tournamentStartTime || '';
    this.model.tournamentEndTime = this.model.tournamentEndTime || '';
    if (this.isFormatSelected('Team Event')) this.model.playersPerTeam = Number(this.model.playersPerTeam || 3);

    const payload: Tournament = JSON.parse(JSON.stringify(this.model));
    if (this.editMode) payload.adminPin = undefined;
    const request = this.editMode && payload.id
      ? this.api.updateTournament(payload.id, payload, this.admin.currentPin())
      : this.api.createTournament(payload);
    if (!this.editMode && this.newTournamentRoster) this.rosterImportBusy = true;
    request.subscribe({
      next: (saved: Tournament) => {
        if (!this.editMode && this.newTournamentRoster) {
          const file = this.newTournamentRoster;
          const pin = payload.adminPin || '';
          if (!saved.id) {
            this.rosterImportBusy = false;
            this.rosterImportMessage = 'Tournament created, but no tournament ID was returned. Please import the roster from Registrations.';
            this.load();
            return;
          }
          this.rosterImportMessage = 'Tournament created. Importing registrations…';
          this.api.uploadRoster(saved.id, '', pin, file).subscribe({
            next: result => {
              this.rosterImportBusy = false;
              this.newTournamentRoster = undefined;
              this.rosterImportMessage = `Tournament created. ${Number(result?.uploaded || 0)} registrations imported, ${Number(result?.skipped || 0)} skipped.`;
              this.load();
            },
            error: err => {
              this.rosterImportBusy = false;
              this.rosterImportMessage = 'Tournament created, but roster import failed: ' + this.displayError(err) + '. You can retry from Registrations.';
              this.load();
            }
          });
          return;
        }
        this.cancelEdit();
        this.load();
      },
      error: err => { this.rosterImportBusy = false; alert(this.displayError(err)); }
    });
  }

  displayError(err:any): string {
    if (!err) return 'Unable to save tournament';
    if (typeof err === 'string') return err;
    if (typeof err?.error === 'string') return err.error;
    if (err?.error?.message) return err.error.message;
    if (err?.message) return err.message;
    try { return JSON.stringify(err.error || err); } catch { return 'Unable to save tournament'; }
  }



  tournamentSchedule(t:Tournament): string {
    const start = t.tournamentDate || '';
    const end = t.tournamentEndDate || '';
    if (start && end && start !== end) return `${start} to ${end}`;
    return start || end || 'Date not set';
  }

  tournamentTime(t:Tournament): string {
    const start = this.formatTime(t.tournamentStartTime || '');
    const end = this.formatTime(t.tournamentEndTime || '');
    if (start && end) return `${start} - ${end}`;
    return start || end || '';
  }

  modelSchedule(): string {
    const start = this.model.tournamentDate || '';
    const end = this.model.tournamentEndDate || '';
    if (this.multiFormatSelected() && start && end && start !== end) return `${start} to ${end}`;
    return start || end || 'Date not set';
  }

  modelTime(): string {
    const start = this.formatTime(this.model.tournamentStartTime || '');
    const end = this.formatTime(this.model.tournamentEndTime || '');
    if (start && end) return `${start} - ${end}`;
    return start || end || '';
  }

  formatTime(value: string): string {
    if (!value) return '';
    const parts = value.split(':');
    const hour = Number(parts[0] || 0);
    const minute = parts[1] || '00';
    if (Number.isNaN(hour)) return value;
    const suffix = hour >= 12 ? 'PM' : 'AM';
    const h12 = hour % 12 || 12;
    return `${h12}:${minute} ${suffix}`;
  }

  viewRegisteredPlayers(t:Tournament){
    this.selectedPlayersTournament = t;
    if(!t.id){ this.selectedTournamentPlayers = []; return; }
    this.api.registrations(t.id).subscribe({
      next: players => this.selectedTournamentPlayers = players || [],
      error: err => alert(this.displayError ? this.displayError(err) : 'Unable to load registered players')
    });
  }
  completeTournament(t:Tournament){ const pin=prompt('Enter tournament Admin PIN'); if(!pin||!t.id)return; this.api.finalizeTournament(t.id,pin).subscribe({next:()=>this.load(),error:e=>alert(this.displayError(e))}); }
  reopenTournament(t:Tournament){ const pin=prompt('Enter tournament Admin PIN'); if(!pin||!t.id)return; this.api.reopenTournament(t.id,pin).subscribe({next:()=>this.load(),error:e=>alert(this.displayError(e))}); }

  editTournament(t:Tournament){
    this.model = JSON.parse(JSON.stringify(t));
    this.model.discountOptions = this.mergeDiscountOptions((this.model.discountOptions as any) || []) as any;
    (this.model.discountOptions as any[]).forEach((d:any) => d.eligibleNamesText = (d.eligibleNames || []).join(', '));
    this.model.adminPin = '';
    this.editMode = true;
    this.showAdminPin = false;
    window.scrollTo({top:0, behavior:'smooth'});
  }
  cancelEdit(){ this.model=this.emptyModel(); this.editMode=false; this.showAdminPin=false; }
  askDelete(t:Tournament){ this.pendingDelete = t; this.deletePin = ''; }
  cancelDelete(){ this.pendingDelete = undefined; this.deletePin = ''; }
  confirmDelete(){
    if(!this.pendingDelete?.id) return;
    this.api.deleteTournament(this.pendingDelete.id,this.deletePin).subscribe({
      next:()=>{ this.cancelDelete(); this.load(); },
      error:err=>alert(err?.error || 'Unable to remove tournament')
    });
  }
}
